#include <bits/stdc++.h>
using namespace std;

vector<long long> dp;

long long solve(int n) {
    if (n <= 1) return n;

    if (dp[n] != -1)
        return dp[n];

    return dp[n] = solve(n - 1) + solve(n - 2);
}

int main() {
    int n;
    cin >> n;

    dp.assign(n + 1, -1);
    cout << solve(n) << '
';

    return 0;
}
